/**
 * Read and rewrite `js/plugins.js`.
 *
 * RPG Maker writes it as:
 *
 *   // Generated by RPG Maker.
 *   // Do not edit this file directly.
 *   var $plugins =
 *   [
 *   {"name":"...","status":true,"description":"...","parameters":{}},
 *   ...
 *   ];
 *
 * The array literal is valid JSON, so we can parse and re-serialise it without
 * evaluating anything.
 *
 * @module core/pluginsfile
 */

import fs from "node:fs";

/**
 * @typedef {{ name: string, status: boolean, description: string, parameters: Record<string,string> }} PluginEntry
 */

/**
 * RPG Maker itself writes a trailing comma before the closing bracket:
 *
 *   {"name":"Last","status":true,...},
 *   ];
 *
 * That is legal JavaScript but illegal JSON, so the literal has to be cleaned
 * before JSON.parse sees it. The scan is textual so commas and brackets inside
 * string literals are left untouched.
 *
 * @param {string} literal
 * @returns {string}
 */
function stripTrailingCommas(literal) {
  let out = "";
  let inString = false;
  let quote = "";
  for (let i = 0; i < literal.length; i += 1) {
    const ch = literal[i];
    if (inString) {
      out += ch;
      if (ch === "\\") {
        out += literal[i + 1] === undefined ? "" : literal[i + 1];
        i += 1;
      } else if (ch === quote) {
        inString = false;
      }
      continue;
    }
    if (ch === '"' || ch === "'") {
      inString = true;
      quote = ch;
      out += ch;
      continue;
    }
    if (ch === "]" || ch === "}") {
      out = out.replace(/,\s*$/, "") + ch;
      continue;
    }
    out += ch;
  }
  return out;
}

/**
 * @param {string} source full text of plugins.js
 * @returns {{ plugins: PluginEntry[], start: number, end: number }}
 */
export function parsePluginsJs(source) {
  const marker = source.indexOf("$plugins");
  if (marker < 0) throw new Error("plugins.js: no $plugins assignment found");
  const open = source.indexOf("[", marker);
  if (open < 0) throw new Error("plugins.js: no array literal found");
  let depth = 0;
  let inString = false;
  let quote = "";
  let end = -1;
  for (let i = open; i < source.length; i += 1) {
    const ch = source[i];
    if (inString) {
      if (ch === "\\") {
        i += 1;
      } else if (ch === quote) {
        inString = false;
      }
      continue;
    }
    if (ch === '"' || ch === "'") {
      inString = true;
      quote = ch;
      continue;
    }
    if (ch === "[") depth += 1;
    else if (ch === "]") {
      depth -= 1;
      if (depth === 0) {
        end = i;
        break;
      }
    }
  }
  if (end < 0) throw new Error("plugins.js: unterminated array literal");
  const literal = source.slice(open, end + 1);
  const plugins = JSON.parse(stripTrailingCommas(literal));
  if (!Array.isArray(plugins)) throw new Error("plugins.js: $plugins is not an array");
  return { plugins, start: open, end };
}

/**
 * Describe the shape of an existing plugins.js so a rewrite can preserve it.
 *
 * @param {string} source full text of plugins.js
 * @returns {{ trailingComma: boolean }}
 */
export function pluginsJsLayout(source) {
  const text = String(source);
  const close = text.lastIndexOf("]");
  // A game checked out with CRLF endings should stay CRLF: rewriting the whole
  // file as LF would show up as a full-file diff in the player's git checkout.
  const eol = text.includes("\r\n") ? "\r\n" : "\n";
  if (close < 0) return { trailingComma: true, eol };
  return { trailingComma: text.slice(0, close).trimEnd().endsWith(","), eol };
}

/**
 * Serialise plugins back using the same layout RPG Maker uses, so diffs stay
 * small and the file still looks original.
 *
 * @param {PluginEntry[]} plugins
 * @param {{ trailingComma?: boolean, eol?: string }} [layout] shape from {@link pluginsJsLayout}
 * @returns {string} full file text
 */
export function serialisePluginsJs(plugins, layout = {}) {
  // RPG Maker's own editor writes a trailing comma before the closing bracket,
  // but plenty of shipped games (and every MV project that went through
  // another tool) end with a plain "\n];". Rewriting the file the other way is
  // still valid JavaScript, yet it turns a one entry edit into a whole-file
  // diff. Remember the original shape and keep it.
  const trailingComma = layout.trailingComma !== false;
  const eol = layout.eol === "\r\n" ? "\r\n" : "\n";
  const body = plugins.map((entry) => JSON.stringify(entry)).join("," + eol);
  return (
    "// Generated by RPG Maker." + eol +
    "// Do not edit this file directly." + eol +
    "var $plugins =" + eol +
    "[" + eol +
    body +
    (trailingComma ? "," + eol + "];" + eol : eol + "];" + eol)
  );
}

/**
 * @param {string} file
 * @returns {PluginEntry[]}
 */
export function readPluginsFile(file) {
  return parsePluginsJs(fs.readFileSync(file, "utf8")).plugins;
}

/**
 * Ensure a plugin entry exists and is enabled.
 *
 * @param {PluginEntry[]} plugins
 * @param {{ name: string, description?: string, parameters?: Record<string,string> }} spec
 * @returns {"added"|"enabled"|"unchanged"}
 */
export function upsertPlugin(plugins, spec) {
  const index = plugins.findIndex((p) => p && p.name === spec.name);
  if (index < 0) {
    plugins.push({
      name: spec.name,
      status: true,
      description: spec.description || "",
      parameters: spec.parameters || {},
    });
    return "added";
  }
  const entry = plugins[index];
  if (entry.status === true) return "unchanged";
  entry.status = true;
  return "enabled";
}

/**
 * @param {PluginEntry[]} plugins
 * @param {string} name
 * @returns {boolean} whether something was removed
 */
export function removePlugin(plugins, name) {
  const index = plugins.findIndex((p) => p && p.name === name);
  if (index < 0) return false;
  plugins.splice(index, 1);
  return true;
}
